        if not s:
            return 0
        return 1 if s == s[::-1] else 2

#include <string>
#include <algorithm>

class Solution {
public:
    int removePalindromeSub(std::string s) {
        if (s.empty()) return 0;
        int l = 0, r = s.size() - 1;
        while (l < r) {
            if (s[l++] != s[r--]) return 2;
        }
        return 1;
    }
};

class Solution {
    public int removePalindromeSub(String s) {
        if (s.isEmpty()) return 0;
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return 2;
        }
        return 1;
    }
}

var removePalindromeSub = function(s) {
    if (!s) return 0;
    let l = 0, r = s.length - 1;
    while (l < r) {
        if (s[l++] !== s[r--]) return 2;
    }
    return 1;
};
